[{"order":1,"type":"heading","text":"File-based Routing Conventions and Special Files in Next.js"},{"order":2,"type":"paragraph","text":"Next.js uses a file-system based router where folders are used to define routes. Each folder represents a route segment that maps to a URL segment. Within this App Router system, specific special files are provided to UI components with distinct roles such as layouts, loading states, error handling, and templates."},{"order":3,"type":"subheading","text":"The Core Special Files Overview"},{"order":4,"type":"bullet_point","text":"page.js: The unique UI for a given route, making the route publicly accessible."},{"order":5,"type":"bullet_point","text":"layout.js: Shared UI for a segment and its children, persisting across navigation and maintaining state."},{"order":6,"type":"bullet_point","text":"template.js: Similar to layouts, but recreates a new instance for each child on navigation."},{"order":7,"type":"bullet_point","text":"loading.js: Instant loading UI for a segment, built on top of React Suspense boundaries."},{"order":8,"type":"bullet_point","text":"error.js: Isolation boundary to catch errors in child segments and render a fallback UI."},{"order":9,"type":"subheading","text":"1. Page Files (page.js)"},{"order":10,"type":"paragraph","text":"A page is UI that is unique to a route. You can make a route publicly accessible by adding a page.js file inside a directory."},{"order":11,"type":"code","text":"// app/dashboard/page.js
export default function DashboardPage() {
  return (
    <div>
      <h1>Welcome to your Dashboard</h1>
    </div>
  );
}"},{"order":12,"type":"subheading","text":"2. Layout Files (layout.js)"},{"order":13,"type":"paragraph","text":"A layout is UI that is shared between multiple pages. You define a layout by default exporting a React component from a layout.js file. The component should accept a children prop that will be populated with a child layout or a child page."},{"order":14,"type":"code","text":"// app/dashboard/layout.js
export default function DashboardLayout({ children }) {
  return (
    <section>
      <nav>Dashboard Navigation Bar</nav>
      {children}
    </section>
  );
}"},{"order":15,"type":"subheading","text":"3. Template Files (template.js)"},{"order":16,"type":"paragraph","text":"Templates are similar to layouts in that they wrap each child layout or page. Unlike layouts that persist across routes and maintain state, templates create a new instance for each of their children on navigation. This means state is not preserved when a user navigates between routes sharing a template."},{"order":17,"type":"code","text":"// app/dashboard/template.js
export default function DashboardTemplate({ children }) {
  return <div className="fade-in">{children}</div>;
}"},{"order":18,"type":"subheading","text":"4. Loading Files (loading.js)"},{"order":19,"type":"paragraph","text":"A loading file creates instant loading UI built on React Suspense. It automatically wraps the page.js file and any children below it in a <Suspense> boundary."},{"order":20,"type":"code","text":"// app/dashboard/loading.js
export default function Loading() {
  return <p>Loading dashboard data...</p>;
}"},{"order":21,"type":"subheading","text":"5. Error Files (error.js)"},{"order":22,"type":"paragraph","text":"An error file conceptually acts as a React Error Boundary that gracefully catches unexpected runtime exceptions in nested child segments. It must be a Client Component using the "use client" directive and typically accepts an error object and a reset function."},{"order":23,"type":"code","text":""use client";

import { useEffect } from "react";

export default function Error({ error, reset }) {
  useEffect(() => {
    console.error(error);
  }, [error]);

  return (
    <div>
      <h2>Something went wrong!</h2>
      <button onClick={() => reset()}>Try again</button>
    </div>
  );
}"}]
